<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Visualizer</title>
<style>
  :root { --bg: #121212; --bar-color: #4caf50; }
  body { background: var(--bg); color: white; font-family: sans-serif; display: flex; flex-direction: column; align-items: center; min-height: 100vh; margin: 0; padding: 20px; box-sizing: border-box;}

  #bars {
    display: flex; justify-content: space-evenly; width: 80%; max-width: 600px; height: 300px; margin-bottom: 20px; background: #1e1e1e; align-items: flex-end; padding-top: 5px; border-radius: 4px;}

  .bar { width: 18px; margin: 0 2px; background-color: var(--bar-color); transition: height 0.2s ease-in-out, transform 0.2s linear; border-radius: 4px 4px 0 0; }

  .controls { display: flex; gap: 15px; margin-top: 20px;}

  button { padding: 8px 16px; font-size: 1rem; cursor: pointer; background-color: #2196F3; color: white; border: none; border-radius: 4px;}
  button:hover { opacity: 0.9; }

</style>
</head>
<body>

<div id="bars"></div>

<button id="sort">Sort</button>
<button id="shuffle">Shuffle</button>
<button id="reset">Reset</button>

<script>
// --- Logic Start ---
const barsContainer = document.getElementById('bars');
let arr = []; // current data array

// Global Sorting State (shared between API and UI)
let state = { i: 0, j: 1 }; 

function resetSortState() {
    state.i = 0; 
    state.j = 0; // Corrected to start at index 0 for first comparison of pair (0,1)
}

// Helper to update DOM bars based on arr content. Uses dynamic scaling.
function updateBars(forceRebuild = false) {
    const currentCount = arr.length;

    if (forceRebuild || document.getElementById('bars').children.length !== currentCount) {
        // Clear and rebuild structure
        barsContainer.innerHTML = ''; 
        for(let val of arr) {
            const div = document.createElement('div');
            div.className = 'bar';
            barsContainer.appendChild(div);
        }
    }

    if(arr.length === 0) return; 

    const bars = document.getElementsByClassName('bar');
    let maxVal = Math.max(...arr);
    if(maxVal <= 1) maxVal = 2; // prevent division by zero

    // Use clientHeight of container. If undefined, default to 300 (CSS defined).
    const containerMaxHt = barsContainer.clientHeight || 300; 

    for(let k=0; k<arr.length && k < bars.length; k++) {
        let val = arr[k];

        const h = (val / maxVal) * containerMaxHt;
        bars[k].style.height = Math.max(2, h) + 'px'; 
    }
}

// API Implementation window.viz
window.viz = {
  array: function() { return arr.slice(); }, // Return copy

  setArray: function(a) {
      if(!a || !Array.isArray(a)) return;
      arr = a.map(x => Math.floor(Math.abs(x))); 

      resetSortState();
      updateBars(true); // Force rebuild DOM to match new array structure/values
  },

  sorted: function() {
      for(let k=1; k<arr.length; k++) {
          if(arr[k] < arr[k-1]) return false;
      }
      return true;
  },

  sortStep: function() {
      const n = arr.length;

      // Handle trivial array case
      if(n <= 1) return true;

      // If sorting is complete according to i index (Bubble Sort passes):
      if(state.i >= n - 1) return true;

      const limit = n - state.i - 1; 

      if(state.j < limit) {
          const u = state.j;
          const v = state.j + 1;

          // Compare and Swap (for ascending sort)
          if(arr[u] > arr[v]) {
              [arr[u], arr[v]] = [arr[v], arr[u]];
          }

          updateBars(); // Update visual heights after potential swap/state change.
          state.j++;
      } else {
          // End of pass, move to next outer iteration
          state.i++;
          state.j = 0;
      }

      return false;
  },
};

// Button Handlers for User Animation (Async loop)
document.getElementById('sort').onclick = async function() {
    if(viz.sorted()) return; // Already sorted

    while(!viz.sorted()) {
        await new Promise(req => setTimeout(req, 20)); // Delay to animate visible steps
        viz.sortStep();
    }
};

document.getElementById('shuffle').onclick = function() {
    let data = [];
    const COUNT = 20; 
    for(let k=1; k<=COUNT; k++) data.push(Math.floor(Math.random()*50)+1);
    window.viz.setArray(data);
};

// Reset sets the array back to a sorted sequence of numbers.
document.getElementById('reset').onclick = function() {
    let data = [];
    for(let k=1; k<=20; k++) data.push(k*5); 
    window.viz.setArray(data); 
};

// Initialize on load with some bars (since script at end of body)
let startData = [];
for(let k=1; k<=20; k++) startData.push(Math.floor(Math.random()*50)+1);
window.viz.setArray(startData);

</script>
</body>
</html>
